import React,{useId,useState} from 'react';
import {useResource} from './state.js';
import {OrganizationPicker} from './OrganizationPicker.jsx';
import {useDialog} from '../dialog.tsx';
import {useWritingRequest} from './writing-request.js';
export function MemoryCreationFields({kind,draft,change,call,novelId,run,busy}){
 const [created,setCreated]=useState([]),{ask}=useDialog(),write=useWritingRequest(call),orgs=useResource(()=>kind==='character_card'?call('writing.organizations.list',{novelId}):Promise.resolve([]),[call,novelId,kind],`${novelId}:organization-options`);
 const options=[...(orgs.value||[]),...created.filter(o=>!(orgs.value||[]).some(x=>x.id===o.id))];
 const choose=ids=>change(old=>({...old,organizationIds:ids,organizationRevisions:{...old.organizationRevisions,...Object.fromEntries(options.map(o=>[o.id,o.revision]))}}));
 const createOrg=async name=>{const title=await ask('新组织名称',name);if(title?.trim())run(async()=>{const org=await write('writing.card.create',{novelId,type:'world_book',name:title.trim(),values:{'world:category':'组织'},reason:'作者新建组织世界书'});setCreated(old=>[...old,{id:org.id,name:org.name,revision:org.revision}]);change(old=>({...old,organizationIds:[...old.organizationIds||[],org.id],organizationRevisions:{...old.organizationRevisions,[org.id]:org.revision}}));});};
 const id=useId(),values=draft.values||{},noRegion=['区域','组织'].includes(String(values['world:category']||'').trim()),set=(key,value)=>change(old=>({...old,values:{...old.values,[key]:value}}));
 return <section className="creation-profile"><h3>{kind==='character_card'?'角色基本资料':'世界条目分类'}</h3><p className="muted">以下均可选；创建时与自由详述一起保存，之后可在资料字段中补充。</p><div className="structure-fields">{kind==='character_card'?<><label>性别说明<input aria-label="新角色性别" value={values['character:gender']||''} placeholder="按角色设定填写" onChange={e=>set('character:gender',e.target.value)}/></label><label>身份／职业<input aria-label="新角色身份" value={values['character:occupation']||''} placeholder="如：学生、治疗师、守门人" onChange={e=>set('character:occupation',e.target.value)}/></label><label>年龄段／描述<input aria-label="新角色年龄描述" placeholder="如：青年，16岁；中年" value={values['character:age']||''} onChange={e=>set('character:age',e.target.value)}/></label><label>出生日期<input aria-label="新角色出生日期" type="date" value={values['character:birth']||''} onChange={e=>set('character:birth',e.target.value)}/></label></>:<><label>类别<input aria-label="新世界条目类别" list={id} value={values['world:category']||''} placeholder="地点、组织、物品…也可自定义" onChange={e=>set('world:category',e.target.value)}/><datalist id={id}>{['地点','组织','物品','规则','种族','历史','其他'].map(t=><option key={t} value={t}/>)}</datalist></label><label>所属区域／组织<input aria-label="新世界条目区域" disabled={noRegion} value={values['world:region']||''} onChange={e=>set('world:region',e.target.value)}/></label><label>适用时期<input aria-label="新世界条目时期" value={values['world:period']||''} onChange={e=>set('world:period',e.target.value)}/></label></>}<label>别名<input aria-label="新资料别名" value={draft.aliasesText||''} placeholder="多个别名用逗号分隔" onChange={e=>change(old=>({...old,aliasesText:e.target.value}))}/></label></div>{kind==='character_card'&&<div><h4>所属组织</h4>{orgs.error&&<p className="notice">{orgs.error.message||String(orgs.error)}</p>}<OrganizationPicker options={options} ids={draft.organizationIds||[]} change={choose} {...{busy}} onCreate={createOrg}/><p className="muted">创建角色时一起建立归属连线；未选择也可直接创建。</p></div>}</section>;
}
